{"type":"tool","tool":"write","callID":"call_00_pRtiLfv4jx1DlfZ0beAG3342","state":{"status":"completed","input":{"content":"import torch


class Normalize:
    """Normalize data using pre-computed mean and std."""

    def __init__(self, mean, std):
        self.mean = torch.as_tensor(mean, dtype=torch.float32)
        self.std = torch.as_tensor(std, dtype=torch.float32)

    def __call__(self, data):
        return (data - self.mean) / (self.std + 1e-8)

    def inverse(self, data):
        return data * self.std + self.mean


class ToTensor:
    """Convert numpy array to torch tensor."""

    def __call__(self, data):
        return torch.as_tensor(data, dtype=torch.float32)


class RandomCrop:
    """Random spatial crop augmentation."""

    def __init__(self, size):
        self.size = size

    def __call__(self, x, y_atm, y_ocn):
        H, W = x.shape[-2], x.shape[-1]
        h, w = self.size
        if H < h or W < w:
            return x, y_atm, y_ocn
        top = torch.randint(0, H - h + 1, (1,)).item()
        left = torch.randint(0, W - w + 1, (1,)).item()
        x = x[..., top:top + h, left:left + w]
        y_atm = y_atm[..., top:top + h, left:left + w]
        y_ocn = y_ocn[..., top:top + h, left:left + w]
        return x, y_atm, y_ocn


class GaussianNoise:
    """Add Gaussian noise for regularization."""

    def __init__(self, std=0.01):
        self.std = std

    def __call__(self, x):
        noise = torch.randn_like(x) * self.std
        return x + noise
